"""Games remain independent from the tool catalog and workspace."""
from html import escape

HELP = {
    '2048': 'Use arrow keys, WASD, swipe, or the direction buttons. Equal tiles merge once per move; their new value adds to your score. New tiles are 2 (90%) or 4 (10%). Reaching 2048 is a milestone: keep playing until no moves remain. One-step Undo is available in Private.',
    'minesweeper': 'Reveal every safe square to win. Your first reveal and its neighbors are safe. Right-click to flag; on touch use Reveal / Flag. Activate an already-open number to reveal its neighbors when the surrounding flag count matches. Incorrect flags can lose the game. Random boards may require a guess. Large boards pan inside the game area.',
    'snake': 'Use arrow keys, WASD, swipe, or the direction buttons. Each food adds 10 points and one segment. Avoid walls and your own body; filling the board wins. Slow, Normal and Fast use 6, 10 and 14 cells per second. Direction changes are accepted once per game tick.',
    'memory-match': 'Select two cards to find a matching pair. Each pair of flips counts as one attempt. A mismatch stays visible for 650 ms; wait before trying again. Match every pair to finish. Fewer attempts rank first, then faster completion.',
}
DETAILS = {
    '2048': ('01', 'Merge. Build. Repeat.', '4 × 4 board', 'Arrow keys / swipe'),
    'minesweeper': ('02', 'A little calculated risk.', '3 difficulties', 'Reveal / flag'),
    'snake': ('03', 'One more bite.', '3 speeds', 'Arrow keys / swipe'),
    'memory-match': ('04', 'Find your other half.', '6–12 pairs', 'Tap to match'),
}


def preview(kind):
    if kind == '2048':
        return '<div class="mini-tiles" aria-hidden="true">' + ''.join(f'<span data-value="{n}">{n}</span>' for n in ['2','4','','8','16','32','4','','','64','128','2','4','','256','2048']) + '</div>'
    if kind == 'mines':
        return '<div class="mini-mines" aria-hidden="true">' + ''.join(f'<span data-value="{n}">{n}</span>' for n in ['','','1','1','','⚑','','2','','1','1','','⚑','','1','','2','','','1','','','1','','']) + '</div>'
    if kind == 'snake':
        return '<svg viewBox="0 0 220 150" aria-hidden="true"><path d="M40 110V50H120V90H175" fill="none" stroke="currentColor" stroke-width="19" stroke-linecap="round" stroke-linejoin="round"/><circle cx="178" cy="86" r="2" fill="#122b24"/><circle cx="178" cy="94" r="2" fill="#122b24"/><circle cx="175" cy="37" r="10" fill="#efbdd9"/><path d="m173 25 4-4" stroke="#b8dbc7" stroke-width="3" stroke-linecap="round"/></svg>'
    return '<div class="mini-memory" aria-hidden="true">' + ''.join(f'<span data-value="{n}">{n}</span>' for n in ['✦','?','?','◈','?','✦','◈','?']) + '</div>'


def directory(games):
    cards = ''.join(f'''<article class="game-card" data-game-card data-game-theme="{g['slug']}" data-category="{g['category'].lower()}" data-search="{escape((g['name']+' '+g['description']).lower(), quote=True)}">
<a href="/games/{g['slug']}/" class="game-cover" aria-label="Play {g['name']}"><span class="game-card-number">{DETAILS[g['slug']][0]}</span>{preview(g['preview'])}<span class="small-tag">{g['category']}</span></a>
<div class="game-card-copy"><p class="game-card-kicker">{DETAILS[g['slug']][1]}</p><h2><a href="/games/{g['slug']}/">{g['name']}</a></h2><p>{g['description']}</p><div class="game-card-meta"><span>{DETAILS[g['slug']][2]}</span><span>Solo</span></div><a href="/games/{g['slug']}/" class="game-card-play">Play game <span aria-hidden="true">↗</span></a></div></article>''' for g in games)
    art = ''.join(f'<div class="games-hero-tile" data-game-theme="{g["slug"]}">{preview(g["preview"])}</div>' for g in games)
    return f'''<section class="container page-section games-page" data-games-directory>
<div class="games-hero"><div class="page-intro"><div class="eyebrow"><span class="game-live-dot"></span> THE PLAY CORNER</div><h1>Small games.<br><em>A little reset.</em></h1><p>Clear a board. Beat your best. Take a breather.<br>Four familiar games, made for a little time to yourself.</p><a class="button primary" href="#games-library">Find your next game <span aria-hidden="true">↘</span></a><div class="games-hero-note"><span>4 games</span><span>Play without signing in</span><span>Your pace</span></div></div><div class="games-hero-art" aria-hidden="true"><div class="games-orbit"></div>{art}<span class="games-art-caption">A SMALL BREAK, WELL PLAYED.</span></div></div>
<section id="games-library" aria-labelledby="games-library-heading"><div class="game-library-heading"><div><div class="eyebrow">PICK YOUR LITTLE CHALLENGE</div><h2 id="games-library-heading">What are we playing?</h2></div><span class="muted">Private play. Public personal bests.</span></div><div class="tools-controls"><label class="search-box">⌕ <input type="search" id="game-search" placeholder="Find a game…" aria-label="Search games"></label><div class="filter-bar" id="game-filters"><button class="filter active" data-game-filter="all" aria-pressed="true">All games</button><button class="filter" data-game-filter="puzzle" aria-pressed="false">Puzzle</button><button class="filter" data-game-filter="arcade" aria-pressed="false">Arcade</button></div></div><div class="games-grid">{cards}</div><p id="games-empty" class="game-empty-state" role="status" hidden>No games found. Try another search.</p></section>
<section class="game-continue panel" aria-labelledby="continue-title"><div class="game-section-heading"><div><div class="eyebrow">RIGHT WHERE YOU LEFT OFF</div><h2 id="continue-title">Continue playing</h2></div><div class="game-save-actions"><button class="button secondary" id="games-sync">Refresh saves</button><button class="text-link" id="games-clear">Clear private saves</button></div></div><p id="game-save-status" role="status">Loading local saves…</p><div id="game-saves"><p>No unfinished games yet. Pick a game above.</p></div><button class="button secondary" id="games-more" hidden>Load more saves</button><button class="button secondary" id="games-copy-guest" hidden>Copy guest saves to account</button></section><p class="games-privacy-note">Guest games stay on this device. Account saves are private. Only verified Public results appear on leaderboards.</p></section>'''


def game_page(game):
    slug, name = game['slug'], game['name']
    number, tagline, spec, controls = DETAILS[slug]
    directions = '<div class="game-dpad" aria-label="Direction controls"><button data-dir="0" aria-label="Move up">↑</button><button data-dir="3" aria-label="Move left">←</button><button data-dir="2" aria-label="Move down">↓</button><button data-dir="1" aria-label="Move right">→</button></div>' if slug in ('2048', 'snake') else ''
    mine_mode = '<div class="game-reveal-switch" id="mine-mode"><button class="button secondary" data-mine-mode="reveal" aria-pressed="true">Reveal</button><button class="button secondary" data-mine-mode="flag" aria-pressed="false">Flag ⚑</button><span id="mine-count" class="muted" role="status"></span></div>' if slug == 'minesweeper' else ''
    undo = '<button class="button secondary" id="game-undo" disabled>Undo one move</button>' if slug == '2048' else ''
    return f'''<section class="container page-section games-page" data-game="{slug}" data-game-theme="{slug}" data-run-state="ready">
<div class="game-page-heading"><div><a class="back-link" href="/games/">← All games</a><div class="eyebrow">GAME {number} <span>/</span> {game['category'].upper()}</div><h1>{name}<span class="accent">.</span></h1><p>{tagline} <span class="muted">{game['description']}</span></p></div><button class="button secondary" id="game-help">How to play <span aria-hidden="true">↗</span></button></div>
<div class="game-layout"><section class="panel game-play"><div class="game-play-topline"><span class="eyebrow">YOUR PLAY SPACE</span><span id="game-run-label" class="game-run-label">Ready to play</span></div><div class="game-settings"><label>Mode<select id="game-mode"><option value="private">Private · saved progress</option><option value="public">Public · Ranked</option></select></label><label>Difficulty<select id="game-difficulty"></select></label></div><p id="game-mode-note" class="muted">Private games can pause and continue later.</p><div class="game-metrics"><div class="game-primary-metric"><span id="game-score-label">Score</span><strong id="game-score">—</strong></div><div><span>Time</span><strong id="game-clock">00:00</strong></div><div><span>Local best</span><strong id="game-best">—</strong></div></div>{mine_mode}
<div class="game-board-shell"><div id="game-board" tabindex="0" role="group" aria-label="{name} board"><div class="game-ready-art">{preview(game['preview'])}</div><div class="game-board-empty"><strong>Your next little challenge.</strong><p>Choose a mode, then press Start game.</p><span>{spec} · {controls}</span></div></div><div id="game-overlay" hidden><span class="eyebrow">TAKE YOUR TIME</span><h2 id="game-overlay-title">Paused</h2><p id="game-overlay-note"></p><button id="game-resume" class="button primary">Continue privately</button></div></div>{directions}<div class="game-actions"><button class="button primary" id="game-start">Start game →</button><button class="button secondary" id="game-pause" disabled>Pause</button><button class="button secondary" id="game-settings-change" hidden>Change settings</button>{undo}<button class="button secondary" id="game-sound" aria-pressed="false">Sound off</button></div><p id="game-status" role="status" aria-live="polite">Ready when you are.</p><div class="game-save-line"><span id="game-save-status" role="status">No game saved yet.</span><button class="text-link" id="game-save-retry">Retry sync</button></div><button id="game-restore" class="button secondary" hidden>Continue saved game · Private</button><button id="game-submit-retry" class="button secondary" hidden>Retry Public submission</button><button id="game-submit-discard" class="button secondary" hidden>Keep pending result Private</button><details class="game-public-disclosure"><summary>About Public &amp; Private play</summary><p>Public games publish your profile name, result and date. Pausing, hiding this page, refreshing or continuing a save makes that run Private. Public timing is verified by the server.</p></details></section>
<aside class="game-side"><section class="panel game-leaderboard"><div class="game-section-heading"><div><div class="eyebrow">A LITTLE FRIENDLY COMPETITION</div><h2>Leaderboard<span class="accent">.</span></h2></div><button id="game-board-refresh" class="text-link">Refresh</button></div><p id="game-board-note" class="muted">Current rules · one best result per player.</p><p id="game-leaderboard-status" role="status">Loading leaderboard…</p><div id="game-leaderboard"></div><div id="game-my-rank"></div><p class="muted small game-rank-disclaimer">A casual leaderboard with replay checks. Automated play cannot be fully prevented.</p></section><section class="panel game-progress-card"><div class="game-progress-symbol" aria-hidden="true">↗</div><div class="eyebrow">MAKE YOURSELF AT HOME</div><h2>A best worth keeping.</h2><p>Pick up your Private saves on another device after sign-in, or find all your Public bests on your profile.</p><div class="game-progress-links"><a class="text-link" href="/games/">Your saved games →</a><a class="text-link" href="/profile/">My Profile →</a></div></section></aside></div>
<dialog id="game-help-dialog"><button class="dialog-close icon-button" aria-label="Close help">×</button><h2>How to play {name}</h2><p>{HELP[slug]}</p><p>Controls work only while the game board is focused. Private progress saves automatically. Public requires sign-in and an uninterrupted completed run; resumed saves cannot enter the board. The mode and difficulty lock during a run. Restart to change them.</p><p>Save failed? Keep this page open and retry sync. Guest saves are separate from account saves. Sound is off until you enable it.</p></dialog></section>'''
